style.css:
@-moz-document domain("managebac.cn") {
/* ----------------------------------
       A. OVERALL CONTAINER & BACKGROUND
       ----------------------------------
    */
    
    /* 1. Target the main content area for a general dark background */
    body, 
    .content-container,
    .main-content {
        background-color: #1c1c1c !important; /* Deep charcoal background */
        color: #e0e0e0 !important;           /* Light gray text */
    }

    /* ----------------------------------
       B. CALENDAR HEADER & SIDEBAR
       ----------------------------------
    */
    
    /* 2. Style the Calendar header bar (the purple section) */
    .page-header, 
    .section-header {
        background-color: #383140 !important; /* Darker, less vibrant purple/gray */
        border-bottom: 1px solid #5a5264 !important;
        color: #f0f0f0 !important;
    }
    
    /* 3. Style the Right Sidebar Panel */
    .right-panel {
        background-color: #252525 !important; 
        border: 1px solid #444 !important;
        border-radius: 8px !important;
        padding: 15px !important; 
    }
    
    /* 4. Make the buttons stand out */
    .btn-primary, .btn-default {
        background-color: #5a5264 !important;
        border-color: #5a5264 !important;
        color: #ffffff !important;
    }


    /* ----------------------------------
       C. CALENDAR GRID
       ----------------------------------
    */

    /* 5. Target the main calendar grid/table area */
    .fullcalendar-view, 
    .fc-unthemed td, 
    .fc-unthemed th {
        background-color: #2b2b2b !important; /* Background for cells/grid */
        color: #e0e0e0 !important;
        border-color: #444444 !important;   /* Subtle border for the grid lines */
    }

    /* 6. Style the headers (Mon, Tue, Wed...) */
    .fc-head .fc-day-header {
        background-color: #333333 !important;
        color: #ffffff !important;
        font-weight: bold !important;
    }

    /* 7. Highlight the current day (if you are on October 2025) */
    .fc-today {
        background-color: #3a3a3a !important; /* A slightly different shade */
    }

    /* ----------------------------------
       D. CALENDAR EVENTS (Tasks)
       ----------------------------------
    */
    
    /* 8. Increase text contrast for event titles */
    .fc-event-title, 
    .fc-event-time {
        color: #ffffff !important;
        font-weight: 500 !important;
        text-shadow: 1px 1px 1px rgba(0, 0, 0, 0.5); /* Helps text pop on colors */
    }

    /* 9. Target the colored boxes for "SUMMATIVE" and "Formative" */
    /* You must inspect these specifically, but here are likely classes: */
    
    .event-summative, 
    .label-summative {
        background-color: #b33939 !important; /* Custom Red for Summative */
    }
    
    .event-formative,
    .label-formative {
        background-color: #486a4f !important; /* Custom Green for Formative */
    }
}
